<script setup lang="ts">
import { computed } from 'vue'
import { KunButton, KunSwitch } from '@kungal/ui-vue'
import { Search, FolderOpen, Sparkles } from 'lucide-vue-next'
import { commonScanDirectory, displayScanPath, filterScanRows, updateScanSelection, type ScanRow, type ScanView } from '../import-workspace'

const props = defineProps<{ rows: ScanRow[]; chosen: string[]; query: string; view: ScanView; autoMatch: boolean; hasApiKey: boolean; matchingUnavailable: boolean; busy: boolean; scanning: boolean; knownGameCount: number; error: string; reloadNeeded: boolean }>()
const emit = defineEmits<{ selection: [ids: string[]]; query: [value: string]; view: [value: ScanView]; autoMatch: [value: boolean]; cancel: []; confirm: []; identify: []; rescan: [] }>()
const visible = computed(() => filterScanRows(props.rows, props.query, props.view))
const common = computed(() => commonScanDirectory(props.rows.map(row => row.candidate)))
const counts = computed(() => ({ all: props.rows.length, new: props.rows.filter(row => row.status === 'new').length, known: props.rows.filter(row => row.status === 'known').length, conflict: props.rows.filter(row => row.status === 'conflict').length }))
const views: { id: ScanView; label: string }[] = [{ id: 'all', label: '全部' }, { id: 'new', label: '可导入' }, { id: 'known', label: '已在书架' }, { id: 'conflict', label: '目录重叠' }]
const scoped = computed(() => props.view !== 'all' || !!props.query.trim())
const visibleChosen = computed(() => visible.value.filter(row => props.chosen.includes(row.candidate.id)).length)
const hiddenChosen = computed(() => props.chosen.length - visibleChosen.value)
const eligibleVisible = computed(() => visible.value.filter(row => row.status === 'new').length)
function select(operation: 'add' | 'remove' | 'only') { if (!props.busy) emit('selection', updateScanSelection(props.chosen, visible.value, operation)) }
function toggle(id: string, checked: boolean) { if (!props.busy) emit('selection', checked ? [...props.chosen, id] : props.chosen.filter(value => value !== id)) }
</script>

<template>
  <div class="import-workspace" :aria-busy="busy || scanning">
    <div class="import-body">
      <p class="import-intro">先选本地目录，再补全作品资料。已在书架与重叠目录不会重复导入。</p>
      <details v-if="common" class="scan-common"><summary>共同目录</summary><p>{{ common }}</p></details>
      <div class="import-match-option"><div><strong><Sparkles :size="15" /> 导入后自动补全封面和资料</strong><p v-if="!hasApiKey">未配置密钥，可先导入，再到资料整理中补全。</p><p v-else-if="matchingUnavailable">当前识别结束后，可在资料整理中继续补全。</p><p v-else>无法确定的作品会保留在待核对列表。</p></div><KunSwitch :model-value="autoMatch" label="导入后自动补全封面和资料" label-class-name="sr-only" :disabled="!hasApiKey || matchingUnavailable || busy" @update:model-value="emit('autoMatch', $event)" /></div>
      <div class="scan-tools"><label class="scan-search"><Search :size="17" /><input :value="query" :disabled="busy" aria-label="筛选扫描结果" placeholder="筛选名称或目录…" @input="emit('query', ($event.target as HTMLInputElement).value)" /></label><div class="scan-views" role="group" aria-label="扫描结果状态"><button v-for="item in views" :key="item.id" :aria-pressed="view === item.id" :disabled="busy" @click="emit('view', item.id)">{{ item.label }} <span>{{ counts[item.id] }}</span></button></div></div>
      <div class="scan-selection"><div><button :disabled="busy || !eligibleVisible" @click="select('add')">{{ scoped ? '选择当前结果' : '全选新游戏' }}</button><button :disabled="busy || !visibleChosen" @click="select('remove')">{{ scoped ? '取消当前结果选择' : '清空选择' }}</button></div><span>当前显示 {{ visible.length }} 项 · 已选 {{ visibleChosen }} 项</span></div>
      <div v-if="hiddenChosen" class="scan-hidden-selection" role="status"><span>筛选外仍选中 {{ hiddenChosen }} 项，确认时一并导入。</span><div><button :disabled="busy" @click="select('only')">仅选择当前结果</button><button :disabled="busy" @click="emit('selection', [])">清空全部选择</button></div></div>
      <div class="scan-list">
        <article v-for="row in visible" :key="row.candidate.id" class="scan-row" :class="`scan-${row.status}`">
          <label><input type="checkbox" :value="row.candidate.id" :checked="chosen.includes(row.candidate.id)" :disabled="row.status !== 'new' || busy" @change="toggle(row.candidate.id, ($event.target as HTMLInputElement).checked)" /><FolderOpen :size="19" /><strong>{{ row.candidate.name }}</strong><span class="scan-status">{{ row.status === 'known' ? '已在书架' : row.status === 'conflict' ? '目录重叠' : '可导入' }}</span></label>
          <div class="scan-row-info"><p class="scan-path">{{ displayScanPath(row.candidate.folderPath, common) }}</p><p v-if="row.status === 'conflict'" class="scan-reason">与「{{ row.owner?.name }}」的安装目录重叠，请先核对已有条目。</p><p v-else-if="row.status === 'known'">已有条目：{{ row.owner?.name }}，个人记录会保留。</p><small>{{ row.candidate.executables.length === 1 ? '发现 1 个启动程序' : `发现 ${row.candidate.executables.length} 个程序，导入后可选择默认启动` }}</small><details><summary :aria-label="`查看完整路径：${row.candidate.name}`">完整路径</summary><p>{{ row.candidate.folderPath }}</p></details></div>
        </article>
        <div v-if="!rows.length" class="scan-empty"><FolderOpen :size="26" /><strong>这个文件夹中没有找到游戏程序。</strong><p>请选择游戏目录或包含游戏的文件夹。扫描不会运行程序。</p><KunButton variant="bordered" size="sm" :loading="scanning" :disabled="busy" @click="emit('rescan')">重新选择文件夹</KunButton></div>
        <div v-else-if="!visible.length" class="scan-empty"><strong>没有符合筛选的目录。</strong><p>筛选只改变显示范围，已选目录仍保留。</p><button :disabled="busy" @click="emit('query', ''); emit('view', 'all')">清除筛选</button></div>
      </div>
    </div>
    <div class="scan-footer">
      <p v-if="error" class="scan-error" role="alert">{{ error }}</p>
      <div class="scan-footer-actions"><KunButton v-if="knownGameCount" variant="bordered" size="sm" :disabled="matchingUnavailable || busy || reloadNeeded" :title="`重新识别扫描范围内已入库的 ${knownGameCount} 部游戏，无需重复导入`" @click="emit('identify')">识别已入库游戏</KunButton><span class="scan-total">共选 {{ chosen.length }} 项</span><KunButton variant="light" size="sm" :disabled="busy" @click="emit('cancel')">取消</KunButton><KunButton color="primary" size="sm" :disabled="!reloadNeeded && !chosen.length" :loading="busy" @click="emit('confirm')">{{ reloadNeeded ? '重新读取书架' : `确认导入 ${chosen.length} 部` }}</KunButton></div>
    </div>
  </div>
</template>

<style>
.kun-modal-panel.import-candidates-modal{display:flex;flex-direction:column;width:min(920px,calc(100vw - 32px));max-width:calc(100vw - 32px);height:min(820px,calc(100dvh - 32px));max-height:calc(100dvh - 32px);overflow:hidden;padding:20px;background:var(--surface);color:var(--ink)}
.import-candidates-modal>div:first-child{flex:none;margin-bottom:12px}
.kun-dark-mode .import-candidates-modal .import-body{color-scheme:dark}
@media(max-width:700px){.kun-modal-panel.import-candidates-modal{padding:14px;min-width:0;width:calc(100vw - 24px);max-width:calc(100vw - 24px);height:calc(100dvh - 24px);max-height:calc(100dvh - 24px)}}
</style>
<style scoped>
.import-workspace{display:flex;flex-direction:column;flex:1;min-height:0;min-width:0;gap:10px;font-size:14px}.import-body{min-height:0;overflow-y:auto;overscroll-behavior:contain;flex:1;padding-right:6px}.import-intro{font-size:13px;line-height:1.6;color:var(--muted);margin:0 0 6px}.scan-common{font-size:12px;margin-bottom:10px;color:var(--muted)}.scan-common p,.scan-row-info details p{overflow-wrap:anywhere;user-select:text;margin-top:5px}.scan-common summary,.scan-row-info summary{cursor:pointer;width:fit-content;color:var(--blue)}.import-match-option{display:flex;align-items:center;gap:16px;padding:10px 12px;margin-bottom:12px;border:1px solid var(--line);background:var(--hover);border-radius:9px}.import-match-option>div:first-child{flex:1;min-width:0}.import-match-option strong{display:flex;align-items:center;gap:6px;font-size:13px;color:var(--ink)}.import-match-option p{margin:4px 0 0;font-size:12px;line-height:1.5;color:var(--muted)}.scan-tools{display:flex;flex-wrap:wrap;gap:9px;margin-bottom:10px}.scan-search{display:flex;align-items:center;gap:8px;border:1px solid var(--line);border-radius:8px;padding:9px 11px;min-width:0;width:100%;margin:0;color:var(--muted)}.scan-search input{width:100%;min-width:0;background:transparent;border:0;outline:none;font-size:14px;color:var(--ink)}.scan-search:focus-within{outline:2px solid var(--blue);outline-offset:1px}.scan-views{display:flex;gap:6px;flex-wrap:wrap}.scan-views button{padding:6px 10px;border:1px solid var(--line);border-radius:7px;font-size:13px;display:flex;align-items:center;gap:7px}.scan-views button[aria-pressed=true]{background:var(--blue-soft);color:var(--blue);border-color:var(--blue)}.scan-views span{font-size:12px;font-variant-numeric:tabular-nums}.scan-selection{display:flex;align-items:center;justify-content:space-between;gap:6px;flex-wrap:wrap;margin:0 0 9px;font-size:12px;color:var(--muted)}.scan-selection>div,.scan-hidden-selection>div{display:flex;gap:14px;flex-wrap:wrap}.scan-selection button,.scan-hidden-selection button,.scan-empty>button{font-size:12px;color:var(--blue)}.scan-hidden-selection{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:7px;padding:9px 11px;margin-bottom:10px;border:1px solid var(--line);background:var(--blue-soft);border-radius:8px;font-size:12px;line-height:1.6}.scan-list{max-height:none;overflow:visible;display:flex;flex-direction:column;gap:8px}.scan-row{border:1px solid var(--line);border-radius:9px;padding:11px 12px;background:var(--surface);min-width:0}.scan-row.scan-known,.scan-row.scan-conflict{background:var(--hover)}.scan-row>label{display:flex;align-items:flex-start;gap:8px;padding:0;border:0;background:transparent;cursor:pointer;min-width:0}.scan-row>label input{margin-top:3px;flex:none;accent-color:var(--blue);width:15px;height:15px}.scan-row>label svg{flex:none;margin-top:1px;color:var(--muted)}.scan-row strong{flex:1;min-width:0;overflow-wrap:anywhere;font-size:14px;line-height:1.5;color:var(--ink)}.scan-status{flex:none;padding:2px 6px;border-radius:4px;font-size:11px;background:var(--blue-soft);color:var(--blue)}.scan-known .scan-status,.scan-conflict .scan-status{background:var(--line);color:var(--muted)}.scan-row-info{margin:5px 0 0 39px;font-size:12px;color:var(--muted);line-height:1.6;overflow-wrap:anywhere}.scan-row-info p{margin:3px 0}.scan-row-info small{font-size:12px}.scan-row-info details{margin-top:4px}.scan-path{font-family:Consolas,"Microsoft YaHei",monospace;font-size:11px}.scan-row-info .scan-reason{color:var(--ink)}.scan-empty{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px;min-height:140px;padding:20px;text-align:center;color:var(--muted)}.scan-empty strong{font-size:14px;color:var(--ink)}.scan-empty p{font-size:12px;line-height:1.6}.scan-footer{flex:none;border-top:1px solid var(--line);padding-top:10px}.scan-footer-actions{display:flex;align-items:center;gap:8px;flex-wrap:wrap;justify-content:flex-end}.scan-total{margin-left:auto;font-size:12px;color:var(--muted)}.scan-error{font-size:13px;line-height:1.6;color:var(--ink);padding:8px 10px;border:1px solid var(--line);background:var(--hover);border-radius:7px;margin-bottom:8px}.import-workspace button:disabled{opacity:.5;cursor:not-allowed}.import-workspace button:focus-visible,.import-workspace summary:focus-visible,.scan-row input:focus-visible{outline:2px solid var(--blue);outline-offset:3px}
@media(max-width:700px){.import-intro{font-size:12px}.import-match-option{padding:8px 10px}.scan-row{padding:10px}.scan-row strong{font-size:13px}.scan-status{font-size:10px}.scan-row-info{margin-left:23px}.scan-row>label svg{display:none}.scan-total{display:none}.scan-views{gap:4px}.scan-views button{padding:5px 8px;font-size:12px}.scan-footer-actions{gap:5px}}
</style>
